class TestLineWithVariable(CodeLine):
    def set_line(self, line):
        temp1 = self.request_temp(
            "test_temporary1", LibRoutineLocalVariable, size=None, dtype="i53"
        )
        temp2 = self.request_temp("test_temporary2", LibRoutineLocalVariable, size=12, dtype="i53")
        super().set_line(
            f"{line} yadayada 42 + {temp2.expr_at(
                1, temp1, 3, 4, simplify=True)}")
        return self


class PTCodeLine(CodeLine):
    """Plain Text version of a StatementLine"""


class PTCommentLine(CommentLine):
    """Plain Text version of a CommentLine"""

    COMMENT_PREFIX = "#> "

    # some_aux_variable = LibRoutineLocalVariable("testvar")


class PTBracketContainer(EnclosingContainer):
    """Plain Text version of a EnvironmentContainer"""

    INDENT_BODY = True

    def set_enclosings(self, open_string, close_string, **buildargs):
        """this method defines the enclosing characters."""
        self.append_head(self.from_text(open_string, **buildargs))
        self.append_foot(self.from_text(close_string, **buildargs))
        return self


class PTLoopContainer(LoopContainer):
    """Plain Text version of a DefinitionContainer"""

    INDENT_BODY = True


class PTDefinitionContainer(DefinitionContainer):
    """Plain Text version of a DefinitionContainer"""

    INDENT_BODY = True

    def build(self):
        self.append_head(PTCodeLine("BEGIN DEFINITION CONTAINER", context=self.context))
        if list(self.captured):
            self.append_head(PTCodeLine("defines:", context=self.context))
        self.append_foot(PTCodeLine("END OF DEFINITION CONTAINER", context=self.context))
        return super().build()

class PTRoutineDefinition(RoutineContainer):
    """Plain Text version of a RoutineDefinition"""

    # routine definition
    # variable initialization
    # body

class PTLibraryDefinition(RoutineContainer):
    """Plain Text version of a RoutineDefinition"""

    # collect all library routines


