class PlainTextBuilder(Builder, identifier="PLAINTEXT"):
    """PlainTextBuilder"""

    def handle_basic_instruction(self, instruction, context, buildargs):
        yield PTCodeLine(f"Unknown instruction {instruction}", context, **buildargs)

    def handle_group_instruction(self, instruction, context, buildargs):
        outer = PTBracketContainer(
            context=context, **buildargs
        ).set_enclosings(
            open_string=f"BEGIN Group {instruction.identifier} {{ ",
            close_string=f"END Group {instruction.identifier} }} ",
        )
        inside_context = context.inherit(parent=outer)
        for inner_instruction in instruction.instructions:
            for inner_container in self.containers_from_instruction(
                inner_instruction,
                inside_context,
                **buildargs,
            ):
                outer.append(inner_container)
        yield outer

    def handle_content_instruction(self, instruction, context, buildargs):
        outer = PTBracketContainer(
            context=context, **buildargs
        ).set_enclosings(
            open_string=f"BEGIN Content Group {instruction.identifier} {{ ",
            close_string=f"END Content Group {instruction.identifier} }} ",
        )
        for key, value in instruction.items():
            if key in ["identifier", "content"]:
                continue
            outer.append(
                PTCodeLine(f":{key}={value}", context=context, **buildargs)
            )
        inside_context = context.inherit(parent=outer)
        for inner_instruction in instruction.content:
            for inner_container in self.containers_from_instruction(
                inner_instruction,
                inside_context,
                **buildargs,
            ):
                outer.append(inner_container)
        yield outer

    def handle_generic_instruction(self, instruction, context, buildargs):
        yield PTCodeLine(f"generic instruction: {instruction.identifier}", context=context, **buildargs)
        for key, value in instruction.items():
            if key in ["identifier"]:
                continue
            yield PTCodeLine(f":{key}={value}", context=context, **buildargs)
        yield TestLineWithVariable("fooo", context=context, **buildargs)

    def handle_routine_instruction(self, instruction, context, buildargs):
        yield from super().handle_routine_instruction(
            instruction, context, buildargs
        )

    def handle_mapapply_instruction(self, instruction, context, buildargs):
        yield from super().handle_mapapply_instruction(
            instruction, context, buildargs
        )

    def handle_variation_instruction(self, instruction, context, buildargs):
        yield from super().handle_variation_instruction(
            instruction, context, buildargs
        )

    def handle_environment_instruction(self, instruction, context, buildargs):
        yield from super().handle_environment_instruction(
            instruction, context, buildargs
        )


PlainTextBuilder.set_default_container("COMMENT", PTCommentLine)
PlainTextBuilder.set_default_container("DEFCONT", PTDefinitionContainer)
PlainTextBuilder.set_default_container("ROUTINE", PTRoutineDefinition)
PlainTextBuilder.set_default_container("LIBRARY", PTLibraryDefinition)


from phoenix.fgen.builder import Context
import sys
from phoenix.fgen.instruction import GenericInstruction, InstructionGroup


a = PlainTextBuilder()

test = InstructionGroup(
    [
        GenericInstruction(foo="bar1", answer=42.1),
        GenericInstruction(foo="bar2", answer=42.2),
        GenericInstruction(foo="bar3", answer=42.3),
        GenericInstruction(foo="bar4", answer=42.4),
        GenericInstruction(foo="bar5", answer=42.5),
    ]
)
ctxt = Context()

largegroup = InstructionGroup([test, test, test])

container_tree = a.generate_container_tree(largegroup)

for indent, line in container_tree.get_codelines():
    print(indent * "  " + line)

sys.exit()
